/* NAUKA OD A DO Z — FIX44 MASTER SERVICE CENTER PRO
 * Local-first service academy. BIOS/disk files are processed read-only in browser memory.
 * No firmware writes, disk writes, router configuration, battery commands or PSU control.
 */
(() => {
  'use strict';
  const BUILD = '6.8.0-fix44';
  const PAGE = document.getElementById('view-fix44');
  const ROOT = document.getElementById('f44Stage');
  const STATUS = document.getElementById('f44Status');
  if (!PAGE || !ROOT || PAGE.dataset.f44Bound === '1') return;
  PAGE.dataset.f44Bound = '1';

  const STORE = 'npNaukaMasterServiceFix44';
  const DB_NAME = 'np-nauka-fix44-library';
  const DB_VERSION = 1;
  const DB_STORE = 'files';
  const MAX_LIBRARY_FILE = 25 * 1024 * 1024;
  const MAX_BIOS_FILE = 32 * 1024 * 1024;
  const MAX_DISK_IMAGE = 64 * 1024 * 1024;
  const $ = (selector, root = PAGE) => root.querySelector(selector);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clean = (value, max = 1200) => String(value ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim().slice(0, max);
  const uid = prefix => `${prefix}-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;
  const now = () => new Date().toISOString();
  const fmt = value => new Intl.NumberFormat('pl-PL', {maximumFractionDigits:2}).format(Number(value || 0));
  const safeJson = (raw, fallback) => { try { return JSON.parse(raw); } catch { return fallback; } };
  const blank = () => ({version:1,models:[],bios:[],thermal:[],battery:[],cases:[],tickets:[],learning:[],simulatorRuns:[],documents:[],network:[],updates:[],qaRuns:[],updatedAt:now()});
  const validRows = (rows, fields) => Array.isArray(rows) ? rows.filter(x => x && typeof x === 'object' && !Array.isArray(x)).slice(0,500).map(x => Object.fromEntries(fields.map(([k,n]) => [k, clean(x[k],n)]))) : [];
  function normalize(input) {
    const s=blank(); if(!input || typeof input!=='object' || Array.isArray(input)) return s;
    s.models=validRows(input.models,[['id',80],['manufacturer',100],['model',160],['boardId',100],['revision',60],['platform',100],['notes',800],['createdAt',40]]).filter(x=>x.model);
    s.bios=validRows(input.bios,[['id',80],['name',180],['sha256',64],['size',30],['date',40],['notes',800]]).filter(x=>x.sha256);
    s.thermal=Array.isArray(input.thermal)?input.thermal.filter(x=>x&&typeof x==='object').slice(0,300).map(x=>({id:clean(x.id,80),device:clean(x.device,160),cpu:Number(x.cpu)||0,gpu:Number(x.gpu)||0,ambient:Number(x.ambient)||0,load:clean(x.load,60),notes:clean(x.notes,700),imageName:clean(x.imageName,180),createdAt:clean(x.createdAt,40)})):[];
    s.battery=Array.isArray(input.battery)?input.battery.filter(x=>x&&typeof x==='object').slice(0,300).map(x=>({id:clean(x.id,80),voltage:Number(x.voltage)||0,current:Number(x.current)||0,power:Number(x.power)||0,profile:clean(x.profile,40),notes:clean(x.notes,500),createdAt:clean(x.createdAt,40)})):[];
    s.cases=Array.isArray(input.cases)?input.cases.filter(x=>x&&typeof x==='object').slice(0,300).map(x=>({id:clean(x.id,80),title:clean(x.title,180),device:clean(x.device,160),symptom:clean(x.symptom,1000),cause:clean(x.cause,1000),resolution:clean(x.resolution,1200),tags:clean(x.tags,300),source:clean(x.source,300),status:clean(x.status,30)||'local',createdAt:clean(x.createdAt,40)})).filter(x=>x.title):[];
    s.tickets=Array.isArray(input.tickets)?input.tickets.filter(x=>x&&typeof x==='object').slice(0,300).map(x=>({id:clean(x.id,80),client:clean(x.client,140),device:clean(x.device,180),serial:clean(x.serial,120),problem:clean(x.problem,1200),status:clean(x.status,40)||'Przyjęte',parts:Number(x.parts)||0,labor:Number(x.labor)||0,notes:clean(x.notes,1000),createdAt:clean(x.createdAt,40)})).filter(x=>x.device):[];
    for(const key of ['learning','simulatorRuns','documents','network','updates','qaRuns']) s[key]=Array.isArray(input[key])?input[key].filter(x=>x&&typeof x==='object'&&!Array.isArray(x)).slice(0,500):[];
    s.updatedAt=clean(input.updatedAt,40)||now(); return s;
  }
  let state=normalize(safeJson(localStorage.getItem(STORE),null));
  function persist(){state.updatedAt=now();localStorage.setItem(STORE,JSON.stringify(state));}
  function status(message, bad=false){if(!STATUS)return;STATUS.textContent=message;STATUS.classList.toggle('is-error',!!bad);STATUS.classList.toggle('is-good',!bad);}
  function button(label,action,kind='secondary',extra=''){return `<button type="button" class="f44-btn ${kind}" data-f44-action="${esc(action)}" ${extra}>${label}</button>`;}
  function card(title,body,kicker='MASTER SERVICE CENTER'){return `<section class="f44-card"><span class="f44-kicker">${esc(kicker)}</span><h2>${title}</h2>${body}</section>`;}
  function empty(text){return `<p class="f44-empty">${esc(text)}</p>`;}
  const tabs=[['overview','Pulpit'],['identify','Laptop ID'],['bios','BIOS Database'],['thermal','Thermal Lab'],['architecture','CPU / GPU Academy'],['battery','Battery & Charging'],['recovery','Data Recovery'],['network','Network Academy'],['explorer','3D Explorer'],['cases','Case Exchange'],['service','Service Manager'],['coach','AI Learning Coach'],['qa','Quality Center'],['simulator','Repair Simulator'],['library','Technical Library'],['updates','Knowledge Update']];
  let active='overview', biosFiles={a:null,b:null}, diskResult=null, thermalPreviewUrl=null, simulator=null, qaResults=[];
  const NAV_LINKS=[['home','Pulpit główny'],['courses','Kursy i lekcje'],['fix43','Centrum Wiedzy FIX43'],['feedback','Oceń stronę / zgłoś problem']];
  const ARCH=[
    {id:'cpu-x86',title:'Procesory x86-64',group:'CPU',text:'ISA, rdzenie, wątki, cache, kontroler pamięci i limity mocy. Konkretna platforma wymaga dokumentacji producenta.'},
    {id:'cpu-arm',title:'Architektura ARM',group:'CPU',text:'Rdzenie energooszczędne i wydajne, SoC, kontrolery I/O oraz boot chain zależny od producenta.'},
    {id:'gpu',title:'GPU i akceleratory',group:'GPU',text:'Jednostki obliczeniowe, VRAM, magistrala PCIe, firmware karty, sterowniki i limity termiczne.'},
    {id:'memory',title:'Hierarchia pamięci',group:'RAM',text:'Rejestry, cache, kontroler pamięci, kanały, DDR4/DDR5 i trening pamięci.'},
    {id:'vrm',title:'VRM i zasilanie',group:'PŁYTA',text:'PWM, MOSFET, dławiki, kondensatory, sprzężenie zwrotne, sygnały EN i PGOOD.'},
    {id:'storage',title:'Storage controllers',group:'SSD',text:'SATA, NVMe, PCIe lanes, kontroler, NAND, wear leveling i SMART.'}
  ];
  const SIMS=[
    {id:'no-power',title:'Laptop bez reakcji na Power',level:'Podstawowy',steps:[
      {q:'Od czego zaczynasz, zanim otworzysz urządzenie?',opts:[['Sprawdzenie zasilacza, przewodu i oględziny',1,'Najpierw potwierdź źródło zasilania i bezpieczny stan urządzenia.'],['Wymiana BIOS',0,'Wymiana firmware bez diagnozy jest nieuzasadniona.'],['Podanie napięcia na losowy punkt',0,'Nigdy nie podawaj napięcia na niezweryfikowany punkt.']]},
      {q:'Chcesz sprawdzić rezystancję na wejściu płyty. Co robisz?',opts:[['Odłącz zasilanie i baterię, rozładuj układ zgodnie z instrukcją',1,'Pomiar rezystancji wykonuj wyłącznie na odłączonym i bezpiecznie rozładowanym obwodzie.'],['Mierzysz przy podłączonym zasilaczu',0,'Pomiar Ω na zasilonym obwodzie grozi uszkodzeniem miernika i płyty.'],['Zewrzesz wejście na próbę',0,'Nie wykonuj zwarć testowych.']]},
      {q:'Brak schematu właściwej rewizji. Jaki jest następny krok?',opts:[['Ustalić Board ID i zdobyć dokumentację zgodną z rewizją',1,'Dopiero zgodna dokumentacja daje wiarygodne punkty pomiarowe.'],['Przyjąć wartości z podobnego laptopa',0,'Podobny model może mieć inną topologię i sekwencję.'],['Wylutować kontroler',0,'Nie wymieniaj elementów bez potwierdzenia usterki.']]}
    ]},
    {id:'overheat',title:'Laptop wyłącza się pod obciążeniem',level:'Średni',steps:[
      {q:'Jak porównujesz zachowanie temperatur?',opts:[['Pomiar w spoczynku i pod kontrolowanym obciążeniem, z logiem',1,'Powtarzalne warunki pozwalają porównać temperatury i taktowanie.'],['Oceniasz temperaturę dłonią',0,'Dotyk nie jest pomiarem i może być niebezpieczny.'],['Od razu zwiększasz napięcie CPU',0,'Zmiana napięć nie jest właściwym krokiem diagnostycznym.']]},
      {q:'Co sprawdzasz przed wymianą chłodzenia?',opts:[['Przepływ powietrza, wentylator, docisk i prawidłowe termopady',1,'Kontrola mechaniczna i zgodność materiałów termicznych jest konieczna.'],['Zmieniasz BIOS',0,'Najpierw wyklucz problem mechaniczny i przepływ powietrza.'],['Wyłączasz zabezpieczenia termiczne',0,'Nie wyłączaj zabezpieczeń chroniących sprzęt.']]}
    ]},
    {id:'nvme',title:'SSD NVMe niewykrywany',level:'Średni',steps:[
      {q:'Co robisz przed próbą naprawy nośnika?',opts:[['Zabezpieczasz dane i pracujesz na kopii/obrazie tylko do odczytu',1,'Najpierw ochrona danych.'],['Inicjalizujesz dysk',0,'Inicjalizacja może nadpisać metadane.'],['Uruchamiasz formatowanie',0,'Formatowanie niszczy szanse odzysku.']]},
      {q:'Jak weryfikujesz kompatybilność M.2?',opts:[['Sprawdzasz klucz, długość, protokół i linie PCIe/SATA',1,'M.2 jest formatem, nie gwarancją zgodności protokołu.'],['Sprawdzasz tylko długość',0,'Długość nie potwierdza protokołu ani klucza.'],['Wkładasz nośnik na siłę',0,'Nie używaj siły przy złączu.']]}
    ]},
    {id:'battery',title:'Bateria nie ładuje',level:'Średni',steps:[
      {q:'Co weryfikujesz jako pierwsze?',opts:[['Zasilacz, przewód, profil PD i stan mechaniczny portu',1,'Zacznij od źródła zasilania i parametrów obsługiwanych przez urządzenie.'],['Rozbierasz ogniwa baterii',0,'Nie otwieraj pakietu ogniw — ryzyko pożaru i obrażeń.'],['Wymuszasz napięcie na stykach baterii',0,'Nie wymuszaj napięcia ani komunikacji z BMS.']]}
    ]}
  ];

  function setTab(name){if(!tabs.some(t=>t[0]===name))return;active=name;PAGE.querySelectorAll('[data-f44-tab]').forEach(b=>{const on=b.dataset.f44Tab===name;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));});render();}
  function stats(){return {models:state.models.length,bios:state.bios.length,thermal:state.thermal.length,tickets:state.tickets.length,cases:state.cases.length,docs:state.documents.length,learning:state.learning.length};}
  function renderOverview(){const s=stats();return `<div class="f44-hero"><div><span class="f44-kicker">MASTER SERVICE CENTER / FIX44</span><h2>Centrum serwisanta <em>i warsztatu PRO</em></h2><p>Identyfikacja urządzeń, dokumentacja, szkolenie, naprawy, kontrola jakości i lokalna wymiana przypadków — w jednym miejscu.</p><div class="f44-actions">${button('Uruchom Repair Simulator','goto-simulator','primary')}${button('Dodaj urządzenie','goto-identify')}</div></div><div class="f44-hero-mark"><b>44</b><span>MASTER</span></div></div><div class="f44-stats">${Object.entries({Urządzenia:s.models,BIOS:s.bios,Termika:s.thermal,Zlecenia:s.tickets,Przypadki:s.cases,Dokumenty:s.docs}).map(([k,v])=>`<div class="f44-stat"><b>${v}</b><span>${k}</span></div>`).join('')}</div><div class="f44-grid two">${card('15 modułów eksperckich',`<p>Każda zakładka ma własny formularz lub symulator. Prywatne wpisy zapisują się lokalnie na tym urządzeniu.</p><div class="f44-link-grid">${tabs.slice(1).map(([id,label])=>`<button class="f44-link" type="button" data-f44-action="goto-${id}"><span>${esc(label)}</span><small>Otwórz moduł →</small></button>`).join('')}</div>`)}${card('Szybkie przejścia',`<div class="f44-link-grid">${NAV_LINKS.map(([id,label])=>`<button class="f44-link" type="button" data-f44-host-view="${id}"><span>${esc(label)}</span><small>Otwórz w aplikacji →</small></button>`).join('')}</div><p class="f44-note">FIX43 pozostaje źródłem wcześniejszych narzędzi: Board Doctor, dokumentów, pomiarów, komponentów, grafu wiedzy i opinii o stronie.</p>`)}</div>`;}

  function renderIdentify(){return `<div class="f44-grid two">${card('Laptop Identification PRO',`<p>Rejestruj dokładny model, producenta, Board ID i rewizję. Dane wpisujesz na podstawie etykiety urządzenia lub oznaczenia laminatu — aplikacja nie zgaduje wariantu płyty.</p><form id="f44ModelForm" class="f44-form"><label>Producent<input name="manufacturer" maxlength="100" placeholder="Lenovo / Dell / HP / ASUS" required></label><label>Model<input name="model" maxlength="160" placeholder="Pełna nazwa modelu" required></label><label>Board ID<input name="boardId" maxlength="100" placeholder="Oznaczenie nadrukowane na PCB"></label><label>Rewizja<input name="revision" maxlength="60" placeholder="REV / Version"></label><label>Platforma<input name="platform" maxlength="100" placeholder="CPU / chipset / platforma"></label><label>Notatki<textarea name="notes" rows="2" maxlength="800"></textarea></label><button class="f44-btn primary" type="submit">Zapisz urządzenie</button></form>`,'01 / IDENTYFIKACJA')}${card('Baza urządzeń',`<label class="f44-search">Szukaj modelu<input id="f44ModelSearch" placeholder="Producent, model, Board ID…"></label><div id="f44ModelList">${renderModels()}</div>`,'DEVICE CATALOG')}</div>`;}
  function renderModels(query=''){const q=String(query).toLowerCase();const rows=state.models.filter(x=>[x.manufacturer,x.model,x.boardId,x.revision,x.platform].join(' ').toLowerCase().includes(q));if(!rows.length)return empty('Brak wpisów. Dodaj pierwszy model, aby zbudować własny katalog.');return rows.map(x=>`<article class="f44-row"><div><b>${esc(x.manufacturer)} ${esc(x.model)}</b><small>Board ID: ${esc(x.boardId||'—')} · REV: ${esc(x.revision||'—')} · ${esc(x.platform||'')}</small><p>${esc(x.notes||'')}</p></div><button class="f44-mini danger" data-f44-action="delete-model" data-id="${esc(x.id)}">Usuń</button></article>`).join('');}

  function renderBios(){return `<div class="f44-grid two">${card('BIOS Database 360 — porównywarka wsadów',`<div class="f44-warning">Pliki BIOS mogą zawierać numery seryjne, klucze i dane urządzenia. Porównanie odbywa się wyłącznie w pamięci przeglądarki. Surowe pliki nie są zapisywane ani wysyłane na serwer. Nie ma funkcji flashowania.</div><form id="f44BiosForm" class="f44-form"><label>Wsad A (.bin / .rom / .fd)<input type="file" name="biosA" accept=".bin,.rom,.fd,.cap,.efi,application/octet-stream" required></label><label>Wsad B do porównania (opcjonalnie)<input type="file" name="biosB" accept=".bin,.rom,.fd,.cap,.efi,application/octet-stream"></label><label>Notatka / model<input name="notes" maxlength="800" placeholder="Model, rewizja, źródło i wersja BIOS"></label><button class="f44-btn primary" type="submit">Oblicz SHA-256 i porównaj</button></form><div id="f44BiosResult" class="f44-result" aria-live="polite"></div>`,'02 / FIRMWARE FORENSICS')}${card('Rejestr sum kontrolnych',`<p>Zapisywane są wyłącznie nazwa, rozmiar, data i SHA-256 — bez binarnej zawartości wsadu.</p><div id="f44BiosList">${renderBiosList()}</div>`,'BIOS INVENTORY')}</div>`;}
  function renderBiosList(){if(!state.bios.length)return empty('Nie dodano jeszcze sum kontrolnych BIOS.');return state.bios.slice().reverse().map(x=>`<article class="f44-row"><div><b>${esc(x.name)}</b><small>${esc(x.size)} bajtów · ${esc(x.date)}</small><code>${esc(x.sha256)}</code><p>${esc(x.notes)}</p></div><button class="f44-mini danger" data-f44-action="delete-bios" data-id="${esc(x.id)}">Usuń</button></article>`).join('');}

  function renderThermal(){return `<div class="f44-grid two">${card('Thermal Diagnostic PRO',`<p>Rejestruj pomiary z termometru lub kamery termowizyjnej. Obraz jest załącznikiem referencyjnym — program nie deklaruje automatycznego odczytu temperatur z pikseli zwykłego zdjęcia.</p><form id="f44ThermalForm" class="f44-form"><label>Urządzenie<input name="device" required maxlength="160" placeholder="Model laptopa / GPU"></label><label>Obciążenie<select name="load"><option>Spoczynek</option><option>Obciążenie lekkie</option><option>Obciążenie średnie</option><option>Obciążenie kontrolowane</option></select></label><label>CPU °C<input name="cpu" type="number" min="-20" max="150" step="0.1" required></label><label>GPU °C<input name="gpu" type="number" min="-20" max="150" step="0.1"></label><label>Otoczenie °C<input name="ambient" type="number" min="-20" max="80" step="0.1"></label><label>Zdjęcie termiczne (opcjonalnie)<input name="image" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="full">Uwagi<textarea name="notes" rows="2" maxlength="700" placeholder="Punkt pomiaru, czas, warunki, czujnik…"></textarea></label><button class="f44-btn primary" type="submit">Zapisz pomiar termiczny</button></form><p id="f44ThermalPreview" class="f44-muted"></p>`,'03 / TERMOWIZJA')}${card('Historia termiczna',`<div id="f44ThermalList">${renderThermalList()}</div>`,'TEMPERATURE HISTORY')}</div>`;}
  function renderThermalList(){if(!state.thermal.length)return empty('Brak zarejestrowanych pomiarów.');return state.thermal.slice().reverse().slice(0,30).map(x=>`<article class="f44-row"><div><b>${esc(x.device)}</b><small>${esc(x.createdAt)} · ${esc(x.load)}</small><p>CPU ${fmt(x.cpu)}°C · GPU ${fmt(x.gpu)}°C · otoczenie ${fmt(x.ambient)}°C</p><small>${esc(x.imageName||'Bez zdjęcia')} ${esc(x.notes)}</small>${x.imageDocId?`<button class="f44-mini" data-f44-action="download-doc" data-id="${esc(x.imageDocId)}">Pobierz zdjęcie</button>`:''}</div><button class="f44-mini danger" data-f44-action="delete-thermal" data-id="${esc(x.id)}">Usuń</button></article>`).join('');}

  function renderArchitecture(){const chosen=safeJson(sessionStorage.getItem('f44ArchSelected'),'cpu-x86');return `<div class="f44-grid two"><section class="f44-card"><span class="f44-kicker">04 / ARCHITECTURE ACADEMY</span><h2>CPU GPU Architecture Academy</h2><p>Moduły omawiają architekturę na poziomie edukacyjnym. Dane o konkretnej generacji lub modelu weryfikuj w oficjalnej dokumentacji.</p><div class="f44-arch-list">${ARCH.map(a=>`<button class="f44-arch-card ${chosen===a.id?'active':''}" data-f44-action="architecture-select" data-id="${a.id}"><span>${esc(a.group)}</span><b>${esc(a.title)}</b></button>`).join('')}</div><div id="f44ArchDetail">${renderArchitectureDetail(chosen)}</div></section>${card('Sprawdź wiedzę',`<form id="f44ArchQuiz" class="f44-form"><p><b>Która część odpowiada za pośredniczenie między rdzeniami CPU a pamięcią operacyjną?</b></p><label class="f44-radio"><input type="radio" name="answer" value="a" required> Kontroler pamięci</label><label class="f44-radio"><input type="radio" name="answer" value="b"> Wentylator</label><label class="f44-radio"><input type="radio" name="answer" value="c"> Złącze HDMI</label><button class="f44-btn primary">Sprawdź odpowiedź</button></form><div id="f44ArchQuizResult" aria-live="polite"></div><p class="f44-note">Wynik zapisuje się w lokalnym profilu nauki i może być użyty przez Learning Coach.</p>`,'KNOWLEDGE CHECK')}</div>`;}
  function renderArchitectureDetail(id){const a=ARCH.find(x=>x.id===id)||ARCH[0];return `<div class="f44-detail"><span>${esc(a.group)}</span><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p><p class="f44-note">Ćwiczenie: narysuj blokowy przepływ sygnałów i wskaż, które dokumenty producenta potwierdzają opis.</p></div>`;}

  function renderBattery(){const logs=state.battery.slice().reverse().slice(0,15);return `<div class="f44-grid two">${card('Battery & Charging Lab',`<p>Oblicz moc z wartości napięcia i prądu oraz zapisz wynik pomiaru. Profile PD są przykładami edukacyjnymi — nie są wysyłane do ładowarki.</p><form id="f44BatteryForm" class="f44-form"><label>Napięcie V<input name="voltage" type="number" min="0" max="60" step="0.01" value="20" required></label><label>Prąd A<input name="current" type="number" min="0" max="10" step="0.01" value="3.25" required></label><label>Profil szkoleniowy<select name="profile"><option>USB-C PD 5 V</option><option>USB-C PD 9 V</option><option>USB-C PD 15 V</option><option selected>USB-C PD 20 V</option><option>Wartość z pomiaru</option></select></label><label>Notatki<textarea name="notes" rows="2" maxlength="500" placeholder="Model zasilacza, warunki pomiaru…"></textarea></label><button class="f44-btn primary">Oblicz moc i zapisz</button></form><div id="f44BatteryResult" class="f44-result"></div><div class="f44-warning">Nie otwieraj pakietów ogniw, nie zwieraj styków, nie wymuszaj napięcia na baterii i nie zmieniaj parametrów BMS.</div>`,'05 / USB-C / BMS')}${card('Historia obliczeń',logs.length?logs.map(x=>`<article class="f44-row"><div><b>${fmt(x.power)} W</b><small>${fmt(x.voltage)} V × ${fmt(x.current)} A · ${esc(x.profile)} · ${esc(x.createdAt)}</small><p>${esc(x.notes)}</p></div><button class="f44-mini danger" data-f44-action="delete-battery" data-id="${esc(x.id)}">Usuń</button></article>`).join(''):empty('Brak zapisanych obliczeń.'),'POWER LOG')}</div>`;}

  function renderRecovery(){return `<div class="f44-grid two">${card('Data Recovery Academy — analiza obrazu tylko do odczytu',`<div class="f44-warning">Wybierz plik obrazu dysku (RAW / IMG / BIN / DD) o rozmiarze do 64 MiB. Analiza odczytuje nagłówki MBR/GPT z kopii w pamięci. Nie zapisuje niczego na wybranym nośniku i nie naprawia partycji.</div><label>Obraz dysku<input id="f44DiskImage" type="file" accept=".img,.bin,.dd,.raw,application/octet-stream"></label><div id="f44DiskResult" class="f44-result" aria-live="polite">Wybierz obraz, aby odczytać sygnatury partycji.</div><div class="f44-actions">${button('Otwórz lekcję odzyskiwania','goto-courses')}</div>`,'06 / DATA RECOVERY')}${card('Zakres analiz edukacyjnych',`<ul class="f44-list"><li>MBR: sygnatura 0x55AA i cztery wpisy partycji podstawowych.</li><li>GPT: sygnatura EFI PART w nagłówku LBA1.</li><li>Rozpoznanie typu partycji i zakresu LBA, jeśli wpis jest poprawny.</li><li>Ostrzeżenie przed inicjalizacją / formatowaniem nośnika z ważnymi danymi.</li><li>Plan odzyskiwania na kopii, nie na oryginale.</li></ul><p class="f44-note">Nie jest to pełny program do odzyskiwania plików, rekonstrukcji RAID ani naprawy systemu plików.</p>`,'READ-ONLY FORENSICS')}</div>`;}

  function ipv4ToInt(ip){const parts=String(ip).split('.');if(parts.length!==4)return null;let n=0;for(const p of parts){if(!/^\d{1,3}$/.test(p)||Number(p)>255)return null;n=((n<<8)|Number(p))>>>0;}return n>>>0;}
  function intToIpv4(n){return [n>>>24,(n>>>16)&255,(n>>>8)&255,n&255].join('.');}
  function calculateSubnet(ip,cidr){const address=ipv4ToInt(ip);const bits=Number(cidr);if(address===null||!Number.isInteger(bits)||bits<0||bits>32)throw new Error('Podaj poprawny adres IPv4 i prefiks 0–32.');const mask=bits===0?0:(0xffffffff<<(32-bits))>>>0;const network=(address&mask)>>>0;const broadcast=(network|(~mask>>>0))>>>0;const hosts=bits>=31?Math.pow(2,32-bits):Math.pow(2,32-bits)-2;return{ip,cidr:bits,mask:intToIpv4(mask),network:intToIpv4(network),broadcast:intToIpv4(broadcast),firstHost:bits>=31?intToIpv4(network):intToIpv4((network+1)>>>0),lastHost:bits>=31?intToIpv4(broadcast):intToIpv4((broadcast-1)>>>0),hostCount:Math.max(0,hosts)};}
  function renderNetwork(){return `<div class="f44-grid two">${card('Network & Router Academy',`<p>Symulator adresacji IPv4 oraz przykładowej segmentacji. Nie łączy się z routerem i nie zmienia jego konfiguracji.</p><form id="f44NetworkForm" class="f44-form"><label>Adres IPv4<input name="ip" value="192.168.10.25" required></label><label>Prefiks CIDR<input name="cidr" type="number" min="0" max="32" value="24" required></label><label>VLAN (opis ćwiczenia)<input name="vlan" type="number" min="1" max="4094" value="10"></label><button class="f44-btn primary">Oblicz podsieć</button></form><div id="f44NetworkResult" class="f44-result"></div>`,'07 / TCP/IP')}${card('Ścieżka nauki sieci',`<div class="f44-steps"><div><b>1. Adresacja</b><span>IPv4, maska, CIDR, brama i broadcast.</span></div><div><b>2. Usługi</b><span>DHCP, DNS, NAT, routing i tablica ARP.</span></div><div><b>3. Segmentacja</b><span>VLAN, trunk/access i izolacja sieci.</span></div><div><b>4. Wi-Fi</b><span>Pasmo, kanał, zabezpieczenia i roaming.</span></div></div>`,'ROUTER TRAINING')}</div>`;}

  function renderExplorer(){return `<div class="f44-grid two"><section class="f44-card"><span class="f44-kicker">08 / 3D ELECTRONICS EXPLORER</span><h2>Interaktywny atlas płyty EDU — perspektywa 3D (SVG)</h2><p>Wybierz element na mapie, aby zobaczyć jego rolę. Widok wykorzystuje ilustrację SVG z perspektywą CSS 3D; nie jest to skan CAD konkretnej płyty producenta.</p><div class="f44-board-wrap"><svg id="f44BoardSvg" viewBox="0 0 640 420" role="img" aria-label="Schemat edukacyjnej płyty głównej z interaktywnymi punktami"><defs><linearGradient id="f44pcb" x2="1" y2="1"><stop stop-color="#124f55"/><stop offset="1" stop-color="#0b2837"/></linearGradient></defs><g id="f44BoardGroup"><rect x="20" y="20" width="600" height="380" rx="24" fill="url(#f44pcb)" stroke="#38d6b1" stroke-width="3"/><path d="M45 80H590 M45 345H590 M85 40V380 M555 40V380 M120 200H530 M200 45V370 M430 45V370" stroke="#53bfa7" stroke-opacity=".35" stroke-width="3" fill="none"/><rect x="235" y="130" width="170" height="150" rx="14" fill="#1e293b" stroke="#70d7ec" stroke-width="3"/><text x="320" y="205" text-anchor="middle" fill="#e8fbff" font-size="22">CPU / SoC</text><rect x="80" y="125" width="95" height="70" rx="8" fill="#26364b" stroke="#91a8c5"/><text x="127" y="164" fill="#e8fbff" text-anchor="middle" font-size="16">RAM</text><rect x="465" y="120" width="105" height="85" rx="8" fill="#26364b" stroke="#91a8c5"/><text x="517" y="168" fill="#e8fbff" text-anchor="middle" font-size="16">VRM</text><rect x="95" y="265" width="120" height="55" rx="8" fill="#26364b" stroke="#91a8c5"/><text x="155" y="297" fill="#e8fbff" text-anchor="middle" font-size="16">BIOS / SPI</text><rect x="445" y="270" width="125" height="55" rx="8" fill="#26364b" stroke="#91a8c5"/><text x="507" y="302" fill="#e8fbff" text-anchor="middle" font-size="16">USB / I/O</text>${[['cpu',320,110],['ram',125,105],['vrm',515,100],['bios',155,250],['io',505,250]].map(([id,x,y])=>`<circle cx="${x}" cy="${y}" r="13" fill="#f59e0b" stroke="#fff" stroke-width="3" data-f44-part="${id}" tabindex="0" role="button" aria-label="Wybierz ${id}"/>`).join('')}</g></svg></div><div class="f44-actions">${button('Obróć 90°','rotate-board')}${button('Resetuj widok','reset-board')}</div></section>${card('Informacje o elemencie',`<div id="f44ExplorerDetail"><span class="f44-kicker">EDU COMPONENT</span><h3>Wybierz punkt na płycie</h3><p>Mapa jest poglądowa. Parametry konkretnego układu sprawdź w jego datasheet i schemacie.</p></div>`,'INTERACTIVE MAP')}</div>`;}
  const PARTS={cpu:['CPU / SoC','Procesor wykonuje instrukcje i integruje zależnie od platformy kontrolery pamięci, grafiki lub I/O.','Sprawdź identyfikację platformy, chłodzenie, zasilanie i dokumentację producenta.'],ram:['RAM','Pamięć operacyjna przechowuje aktywne dane i instrukcje. Generacja, topologia i parametry zależą od kontrolera.','Zweryfikuj DDR4/DDR5, obsługiwane moduły, kanały i trening pamięci.'],vrm:['VRM','Przetwornica zasilająca generuje wymagane domeny napięć z wejścia.','Schemat, kontroler PWM, MOSFET, indukcyjność, pomiary i sekwencja EN/PGOOD.'],bios:['BIOS / SPI','Pamięć SPI może przechowywać firmware platformy i dane konfiguracyjne.','Zidentyfikuj kość, pojemność, napięcie i właściwy wsad; nie zapisuj bez procedury i backupu.'],io:['USB / I/O','Kontrolery I/O łączą porty, magistrale i urządzenia peryferyjne.','Sprawdź port, ochronę ESD, linie sygnałowe, kontroler i sterowniki.']};

  function renderCases(){return `<div class="f44-grid two">${card('Repair Case Marketplace — wymiana lokalna',`<p>Twórz przypadki napraw i wymieniaj je plikami JSON z innymi użytkownikami. W tej wersji nie ma publicznej, globalnej publikacji — importowane wpisy są oznaczane jako niezweryfikowane do czasu sprawdzenia przez instruktora.</p><form id="f44CaseForm" class="f44-form"><label>Tytuł przypadku<input name="title" maxlength="180" required></label><label>Urządzenie / model<input name="device" maxlength="160"></label><label class="full">Objaw<textarea name="symptom" maxlength="1000" required rows="2"></textarea></label><label class="full">Potwierdzona przyczyna<textarea name="cause" maxlength="1000" rows="2"></textarea></label><label class="full">Rozwiązanie i test końcowy<textarea name="resolution" maxlength="1200" rows="3"></textarea></label><label>Tagi<input name="tags" maxlength="300" placeholder="BIOS, brak-obrazu, NVMe"></label><label>Źródło / autor<input name="source" maxlength="300" placeholder="Własny przypadek / dokumentacja"></label><button class="f44-btn primary">Zapisz przypadek lokalnie</button></form><div class="f44-actions">${button('Eksportuj pakiet przypadków','export-cases')}${button('Importuj pakiet JSON','import-cases')}</div><input id="f44CaseImport" type="file" accept="application/json,.json" hidden>`,'09 / CASE EXCHANGE')}${card('Lokalna baza przypadków',`<div id="f44CaseList">${renderCaseList()}</div>`,'CASE LIBRARY')}</div>`;}
  function renderCaseList(){if(!state.cases.length)return empty('Brak przypadków. Dodaj własny opis naprawy lub zaimportuj pakiet JSON.');return state.cases.slice().reverse().map(x=>`<article class="f44-row"><div><b>${esc(x.title)}</b><small>${esc(x.device)} · ${esc(x.status)} · ${esc(x.createdAt)}</small><p><b>Objaw:</b> ${esc(x.symptom)}</p><p><b>Przyczyna:</b> ${esc(x.cause||'Niepotwierdzona')}</p><p><b>Rozwiązanie:</b> ${esc(x.resolution||'Brak wpisu')}</p><small>Źródło: ${esc(x.source||'Nie podano')}</small></div><div class="f44-row-actions"><button class="f44-mini" data-f44-action="verify-case" data-id="${esc(x.id)}">Zweryfikuj</button><button class="f44-mini danger" data-f44-action="delete-case" data-id="${esc(x.id)}">Usuń</button></div></article>`).join('');}

  function renderService(){return `<div class="f44-grid two">${card('Serwisant Professional Manager',`<p>Lokalny rejestr zleceń. Wprowadzaj wyłącznie dane niezbędne do ćwiczeń lub obsługi własnego warsztatu. Nie wysyłaj danych klientów do publicznych pakietów przypadków.</p><form id="f44TicketForm" class="f44-form"><label>Klient / identyfikator<input name="client" maxlength="140" placeholder="Np. Klient-001"></label><label>Urządzenie<input name="device" maxlength="180" required placeholder="Laptop / PC / model"></label><label>Numer seryjny (opcjonalnie)<input name="serial" maxlength="120"></label><label>Status<select name="status"><option>Przyjęte</option><option>Diagnostyka</option><option>Oczekuje na części</option><option>Naprawa</option><option>Testy końcowe</option><option>Gotowe</option><option>Wydane</option></select></label><label class="full">Opis usterki<textarea name="problem" maxlength="1200" rows="2" required></textarea></label><label>Części PLN<input name="parts" type="number" min="0" max="100000" step="0.01" value="0"></label><label>Robocizna PLN<input name="labor" type="number" min="0" max="100000" step="0.01" value="0"></label><label class="full">Notatki<textarea name="notes" maxlength="1000" rows="2"></textarea></label><button class="f44-btn primary">Dodaj zlecenie</button></form>`,'10 / SERVICE DESK')}${card('Zlecenia i raporty',`<div class="f44-actions">${button('Drukuj listę zleceń','print-tickets')}${button('Eksportuj dane','export-service')}</div><div id="f44TicketList">${renderTicketList()}</div>`,'LOCAL WORK ORDERS')}</div>`;}
  function renderTicketList(){if(!state.tickets.length)return empty('Brak zleceń.');return state.tickets.slice().reverse().map(x=>`<article class="f44-row"><div><b>${esc(x.device)} · ${fmt(x.parts+x.labor)} zł</b><small>${esc(x.id)} · ${esc(x.client||'bez klienta')} · ${esc(x.status)}</small><p>${esc(x.problem)}</p><small>Nr seryjny: ${esc(x.serial||'—')} · części ${fmt(x.parts)} zł + robocizna ${fmt(x.labor)} zł</small><p>${esc(x.notes)}</p><label class="f44-inline">Status<select data-f44-ticket-status="${esc(x.id)}">${['Przyjęte','Diagnostyka','Oczekuje na części','Naprawa','Testy końcowe','Gotowe','Wydane'].map(st=>`<option ${st===x.status?'selected':''}>${st}</option>`).join('')}</select></label></div><button class="f44-mini danger" data-f44-action="delete-ticket" data-id="${esc(x.id)}">Usuń</button></article>`).join('');}

  function renderCoach(){const recent=state.learning.slice(-10);const done=state.simulatorRuns.reduce((n,x)=>n+(Number(x.score)||0),0);const rec=[];if(!state.models.length)rec.push('Dodaj urządzenie z prawidłowym Board ID i rewizją.');if(!state.bios.length)rec.push('Przećwicz sumę SHA-256 i porównanie dwóch wsadów BIOS na plikach edukacyjnych.');if(!state.thermal.length)rec.push('Zapisz serię pomiarów temperatur w spoczynku i pod obciążeniem.');if(!state.cases.length)rec.push('Utwórz pierwszy przypadek naprawy z potwierdzonym testem końcowym.');if(!state.documents.length)rec.push('Dodaj dokumentację producenta do biblioteki technicznej.');if(!rec.length)rec.push('Masz podstawowe dane. Wykonaj scenariusz Repair Simulator i uzupełnij brakujące dowody.');return `<div class="f44-grid two">${card('AI Learning Coach — plan adaptacyjny',`<p>W tej wersji trener wykorzystuje lokalne dane, wyniki ćwiczeń i reguły rekomendacji. Nie udaje generatywnego modelu AI. Możesz przekazać temat do istniejącego czatu platformy.</p><div class="f44-coach-score"><b>${recent.length+done}</b><span>zapisane aktywności / punkty symulacji</span></div><h3>Twój następny plan</h3><ol class="f44-list">${rec.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="f44-actions">${button('Przejdź do symulatora','goto-simulator','primary')}${button('Otwórz czat platformy','goto-cloudchat')}</div>`,'11 / PERSONAL LEARNING')}${card('Historia nauki',recent.length?recent.slice().reverse().map(x=>`<article class="f44-row"><div><b>${esc(x.title||x.module||'Ćwiczenie')}</b><small>${esc(x.createdAt||'')} · ${esc(x.result||'zapisano')}</small></div></article>`).join(''):empty('Brak aktywności. Ukończ quiz architektury lub symulację naprawy.'),'LEARNING HISTORY')}</div>`;}

  function renderQA(){return `<div class="f44-grid two">${card('Centrum kontroli jakości aplikacji',`<p>Uruchom lokalne kontrole dostępności modułów, pamięci, obliczeń i kontraktów. Test nie zastępuje E2E, skanowania bezpieczeństwa ani testu na serwerze produkcyjnym.</p><div class="f44-actions">${button('Uruchom pełną kontrolę','run-qa','primary')}${button('Eksportuj raport QA','export-qa')}</div><div id="f44QAResults">${renderQAResults()}</div>`,'12 / APPLICATION HEALTH')}${card('Zakres kontroli',`<ul class="f44-list"><li>Istnienie 15 modułów FIX44 i poprzednich widoków.</li><li>Odczyt i zapis pamięci lokalnej.</li><li>Poprawność kalkulatora IPv4/CIDR.</li><li>Poprawność obliczania mocy W = V × A.</li><li>Odczyt sygnatur MBR/GPT bez zapisu.</li><li>Obecność plików CSS/JS w HTML i cache PWA.</li><li>Sprawdzenie podstawowych elementów nawigacji.</li></ul><p class="f44-note">Po wdrożeniu należy wykonać osobny test E2E, test API i sprawdzenie logów Cloudflare.</p>`,'RELEASE READINESS')}</div>`;}
  function renderQAResults(){if(!qaResults.length)return empty('Kontrola nie była jeszcze uruchamiana.');return `<div class="f44-qa-results">${qaResults.map(x=>`<div class="f44-qa-row ${x.ok?'pass':'fail'}"><b>${x.ok?'PASS':'FAIL'}</b><span>${esc(x.name)}</span><small>${esc(x.detail||'')}</small></div>`).join('')}</div>`;}
  function runSelfChecks(){const checks=[];const check=(name,fn)=>{try{const r=fn();checks.push({name,ok:r!==false,detail:r===true?'OK':String(r??'OK')});}catch(e){checks.push({name,ok:false,detail:e.message});}};
    check('FIX44 runtime API',()=>typeof window.NP_NAUKA_FIX44==='object');
    check('Widok FIX43 zachowany',()=>!!document.getElementById('view-fix43'));
    check('Zakładka opinii zachowana',()=>!!document.getElementById('view-feedback'));
    check('16 obszarów nawigacji FIX44',()=>PAGE.querySelectorAll('[data-f44-tab]').length===tabs.length);
    check('Pamięć lokalna odczyt/zapis',()=>{const k='np-f44-qa-temp';localStorage.setItem(k,'ok');const v=localStorage.getItem(k);localStorage.removeItem(k);return v==='ok';});
    check('IPv4/CIDR 192.168.1.42/24',()=>calculateSubnet('192.168.1.42',24).network==='192.168.1.0');
    check('Obliczenie mocy 20 V × 3,25 A',()=>Math.abs(20*3.25-65)<0.001);
    check('MBR signature parser',()=>parseDiskHeader(new Uint8Array(512).fill(0),512).mbrSignature===false);
    check('Walidacja nazwy Board ID',()=>clean('EDU-BOARD-01',100)==='EDU-BOARD-01');
    check('Ochrona prywatnych plików BIOS',()=>!Object.values(state.bios).some(x=>x&&x.binary));
    check('Cache PWA zawiera FIX44',()=>PAGE.ownerDocument.querySelector('script[src*="master-service-center-fix44.js"]')!==null);
    check('Nawigacja do poprzednich modułów',()=>!!document.querySelector('[data-view="fix43"]')&&!!document.querySelector('[data-view="feedback"]'));
    state.qaRuns.unshift({id:uid('QA'),createdAt:now(),passed:checks.filter(x=>x.ok).length,total:checks.length});state.qaRuns=state.qaRuns.slice(0,100);persist();return checks;
  }

  function renderSimulator(){if(!simulator)return `<div class="f44-grid two">${card('Repair Simulator WORLD',`<p>Praktyczne scenariusze krok po kroku. Oceniane są kolejność diagnostyki i bezpieczeństwo. Zadania są symulowane i nie sterują prawdziwym sprzętem.</p><div class="f44-sim-cards">${SIMS.map(s=>`<button type="button" class="f44-sim-card" data-f44-action="start-sim" data-id="${s.id}"><span>${esc(s.level)}</span><b>${esc(s.title)}</b><small>Rozpocznij ćwiczenie →</small></button>`).join('')}</div>`,'13 / WORLD SIMULATOR')}${card('Najlepsze wyniki',state.simulatorRuns.length?state.simulatorRuns.slice().reverse().slice(0,10).map(x=>`<article class="f44-row"><div><b>${esc(x.title)}</b><small>${esc(x.createdAt)} · ${x.score}/${x.total} pkt</small></div></article>`).join(''):empty('Brak wyników. Wybierz scenariusz.'),'CHALLENGE HISTORY')}</div>`;
    const s=SIMS.find(x=>x.id===simulator.id);if(!s)return '';const q=s.steps[simulator.index];return `<section class="f44-card f44-sim-session"><span class="f44-kicker">REPAIR SIMULATOR WORLD / ${esc(s.level)}</span><div class="f44-progress"><span style="width:${Math.round(simulator.index/s.steps.length*100)}%"></span></div><h2>${esc(s.title)}</h2><p class="f44-muted">Pytanie ${simulator.index+1} z ${s.steps.length} · Punkty: ${simulator.score}</p><h3>${esc(q.q)}</h3><div class="f44-options">${q.opts.map((o,i)=>`<button class="f44-option" data-f44-action="sim-answer" data-index="${i}">${esc(o[0])}</button>`).join('')}</div><div id="f44SimFeedback" aria-live="polite"></div><div class="f44-actions">${button('Zakończ ćwiczenie','quit-sim')}</div></section>`;}

  function renderLibrary(){return `<div class="f44-grid two">${card('Universal Technical Library',`<p>Lokalna biblioteka dokumentacji. Pliki są przechowywane w IndexedDB tej przeglądarki (limit 25 MB na plik). Nie są wysyłane na serwer i mogą zostać utracone po wyczyszczeniu danych przeglądarki — wykonuj kopie.</p><form id="f44DocForm" class="f44-form"><label>Dokument / datasheet<input type="file" name="file" accept=".pdf,.txt,.md,.csv,.json,.png,.jpg,.jpeg,.webp,.zip" required></label><label>Tagi / kategoria<input name="tags" maxlength="250" placeholder="Board ID, BIOS, datasheet, model"></label><label>Źródło dokumentacji<input name="source" maxlength="300" placeholder="Oficjalny producent / własne opracowanie"></label><button class="f44-btn primary">Dodaj do biblioteki offline</button></form><label class="f44-search">Szukaj w dokumentach<input id="f44DocSearch" placeholder="Nazwa, tagi, źródło…"></label><div id="f44DocList">${renderDocList()}</div>`,'14 / LOCAL DOCUMENT LIBRARY')}${card('Zasady dokumentacji',`<ul class="f44-list"><li>Zachowuj oryginalną nazwę i źródło.</li><li>Oznacz dokument jako oficjalny tylko po sprawdzeniu domeny producenta.</li><li>Nie publikuj cudzych plików bez praw do udostępniania.</li><li>Nie traktuj dokumentacji podobnego modelu jako schematu własnej rewizji.</li><li>Pliki są lokalne. Eksport danych nie dołącza surowych plików automatycznie.</li></ul>`,'DOCUMENT SAFETY')}</div>`;}
  function renderDocList(query=''){const q=String(query).toLowerCase();const rows=state.documents.filter(x=>[x.name,x.tags,x.source].join(' ').toLowerCase().includes(q));if(!rows.length)return empty('Brak dokumentów.');return rows.map(x=>`<article class="f44-row"><div><b>${esc(x.name)}</b><small>${fmt(x.size/1024)} KiB · ${esc(x.tags||'bez tagów')}</small><p>${esc(x.source)}</p><small>${esc(x.createdAt)}</small></div><div class="f44-row-actions"><button class="f44-mini" data-f44-action="download-doc" data-id="${esc(x.id)}">Pobierz</button><button class="f44-mini danger" data-f44-action="delete-doc" data-id="${esc(x.id)}">Usuń</button></div></article>`).join('');}

  function renderUpdates(){return `<div class="f44-grid two">${card('Global Knowledge Update',`<p>Sprawdzanie obejmuje manifest katalogu źródeł i pakietów wiedzy opublikowany razem z aplikacją. Nie pobieramy automatycznie niezweryfikowanych firmware ani płatnych schematów. Dokumenty dodawaj ze źródłem i prawami do użycia.</p><div class="f44-actions">${button('Sprawdź manifest aktualizacji','check-updates','primary')}${button('Importuj manifest JSON','import-update')}</div><input type="file" id="f44UpdateFile" accept="application/json,.json" hidden><div id="f44UpdateResult" class="f44-result">Nie sprawdzono manifestu w tej sesji.</div><div id="f44UpdateSources" class="f44-source-list">${renderSources()}</div>`,'15 / KNOWLEDGE SYNC')}${card('Pakiet wiedzy EDU',`<p>Wersjonowany indeks źródeł, nie zbiór automatycznie pobranych datasheetów. Użytkownik może importować aktualizacje JSON po sprawdzeniu SHA-256 i pochodzenia.</p><div class="f44-actions">${button('Eksportuj indeks źródeł','export-sources')}${button('Eksportuj dane FIX44','export-state')}</div><div class="f44-detail"><b>Bezpieczny proces aktualizacji</b><ol><li>Sprawdź domenę i licencję źródła.</li><li>Pobierz dokument bezpośrednio od producenta.</li><li>Dodaj dokument do biblioteki lokalnej.</li><li>Zapisz wersję, datę i sumę kontrolną.</li></ol></div>`,'UPDATE MANAGEMENT')}</div>`;}
  const SOURCES=[
    {name:'Intel Product Specifications',category:'CPU / platforma',url:'https://ark.intel.com/'},
    {name:'AMD Product Specifications',category:'CPU / GPU',url:'https://www.amd.com/en/products/specifications.html'},
    {name:'NVIDIA Developer Documentation',category:'GPU / compute',url:'https://docs.nvidia.com/'},
    {name:'Microsoft Learn',category:'Windows / sieci',url:'https://learn.microsoft.com/'},
    {name:'USB Implementers Forum',category:'USB / USB-C',url:'https://www.usb.org/'},
    {name:'PCI-SIG',category:'PCI Express',url:'https://pcisig.com/'},
    {name:'NVM Express',category:'NVMe',url:'https://nvmexpress.org/'},
    {name:'JEDEC',category:'Pamięci',url:'https://www.jedec.org/'},
    {name:'UEFI Forum',category:'UEFI',url:'https://uefi.org/'},
    {name:'Wi-Fi Alliance',category:'Wi-Fi',url:'https://www.wi-fi.org/'}
  ];
  function renderSources(){return SOURCES.map(x=>`<a class="f44-source" href="${x.url}" target="_blank" rel="noopener noreferrer"><b>${esc(x.name)}</b><small>${esc(x.category)}</small></a>`).join('');}

  function render(){const views={overview:renderOverview,identify:renderIdentify,bios:renderBios,thermal:renderThermal,architecture:renderArchitecture,battery:renderBattery,recovery:renderRecovery,network:renderNetwork,explorer:renderExplorer,cases:renderCases,service:renderService,coach:renderCoach,qa:renderQA,simulator:renderSimulator,library:renderLibrary,updates:renderUpdates};ROOT.innerHTML=(views[active]||renderOverview)();PAGE.querySelectorAll('[data-f44-tab]').forEach(b=>{const on=b.dataset.f44Tab===active;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));});}

  function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  function exportJSON(data,name){downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),name);}
  async function sha256(buffer){const digest=await crypto.subtle.digest('SHA-256',buffer);return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');}
  function compareBios(a,b){const aa=new Uint8Array(a),bb=new Uint8Array(b),max=Math.max(aa.length,bb.length);let diff=0;const ranges=[];let start=-1;for(let i=0;i<max;i++){const different=aa[i]!==bb[i];if(different){diff++;if(start<0)start=i;}else if(start>=0){ranges.push([start,i-1]);start=-1;}}if(start>=0)ranges.push([start,max-1]);return{bytesA:aa.length,bytesB:bb.length,differentBytes:diff,changedRanges:ranges.length,ranges:ranges.slice(0,30),sameLength:aa.length===bb.length};}
  function parseDiskHeader(bytes,size){const data=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);const sig=data.length>=512&&data[510]===0x55&&data[511]===0xAA;const get32=o=>(data[o]|(data[o+1]<<8)|(data[o+2]<<16)|(data[o+3]<<24))>>>0;const partitions=[];if(sig){for(let i=0;i<4;i++){const o=446+i*16,type=data[o+4],start=get32(o+8),sectors=get32(o+12);if(type||start||sectors)partitions.push({index:i+1,type:`0x${type.toString(16).padStart(2,'0')}`,startLBA:start,sectors});}}const gpt=data.length>=1024&&String.fromCharCode(...data.slice(512,520))==='EFI PART';return{size,mbrSignature:sig,gptSignature:gpt,partitions,readOnly:true};}

  function openDb(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB niedostępne'));return;}const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(DB_STORE))db.createObjectStore(DB_STORE,{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('Nie można otworzyć IndexedDB'));});}
  async function storeLibraryFile(file,tags,source){if(file.size>MAX_LIBRARY_FILE)throw new Error('Plik przekracza limit 25 MiB.');const db=await openDb();const id=uid('DOC');const data=await file.arrayBuffer();await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put({id,name:file.name,type:file.type||'application/octet-stream',data,createdAt:now()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();state.documents.unshift({id,name:clean(file.name,200),type:clean(file.type,100),size:file.size,tags:clean(tags,250),source:clean(source,300),createdAt:now()});state.documents=state.documents.slice(0,500);persist();return id;}
  async function getLibraryFile(id){const db=await openDb();const row=await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly');const req=tx.objectStore(DB_STORE).get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});db.close();return row||null;}
  async function deleteLibraryFile(id){const db=await openDb();await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();state.documents=state.documents.filter(x=>x.id!==id);persist();}

  function navigateHost(view){const btn=document.querySelector(`[data-view="${view}"]`);if(btn){btn.click();return true;}status(`Nie znaleziono widoku ${view} w tej kopii aplikacji.`,true);return false;}
  function addLearning(title,result){state.learning.push({id:uid('LEARN'),title, result,createdAt:now()});state.learning=state.learning.slice(-500);persist();}
  function addModel(row){state.models.unshift({id:uid('MODEL'),manufacturer:clean(row.manufacturer,100),model:clean(row.model,160),boardId:clean(row.boardId,100),revision:clean(row.revision,60),platform:clean(row.platform,100),notes:clean(row.notes,800),createdAt:now()});persist();}
  function addTicket(row){state.tickets.unshift({id:uid('WO'),client:clean(row.client,140),device:clean(row.device,180),serial:clean(row.serial,120),status:clean(row.status,40)||'Przyjęte',problem:clean(row.problem,1200),parts:Math.max(0,Math.min(100000,Number(row.parts)||0)),labor:Math.max(0,Math.min(100000,Number(row.labor)||0)),notes:clean(row.notes,1000),createdAt:now()});persist();}
  function addCase(row){state.cases.unshift({id:uid('CASE'),title:clean(row.title,180),device:clean(row.device,160),symptom:clean(row.symptom,1000),cause:clean(row.cause,1000),resolution:clean(row.resolution,1200),tags:clean(row.tags,300),source:clean(row.source,300),status:'local',createdAt:now()});persist();}
  function deleteRow(key,id){state[key]=state[key].filter(x=>x.id!==id);persist();render();}
  function handleSubmit(event){const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const v=Object.fromEntries(new FormData(form).entries());
    if(form.id==='f44ModelForm'){addModel({manufacturer:clean(v.manufacturer,100),model:clean(v.model,160),boardId:clean(v.boardId,100),revision:clean(v.revision,60),platform:clean(v.platform,100),notes:clean(v.notes,800)});render();status('Urządzenie dodane do lokalnego katalogu.');}
    if(form.id==='f44BiosForm')processBios(form,v).catch(e=>{const out=$('#f44BiosResult');if(out)out.textContent=e.message;status(e.message,true);});
    if(form.id==='f44ThermalForm'){const f=form.elements.image.files[0];if(f&&(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>8*1024*1024)){status('Zdjęcie musi być PNG/JPEG/WebP do 8 MiB.',true);return;}const save=async()=>{let imageDocId='';if(f)imageDocId=await storeLibraryFile(f,'Termowizja / dowód pomiaru',`Pomiar termiczny: ${clean(v.device,160)}`);const row={id:uid('THERM'),device:clean(v.device,160),cpu:Number(v.cpu),gpu:Number(v.gpu),ambient:Number(v.ambient),load:clean(v.load,60),notes:clean(v.notes,700),imageName:f?clean(f.name,180):'',imageDocId,createdAt:now()};state.thermal.unshift(row);persist();render();status(f?'Pomiar i zdjęcie termiczne zapisano lokalnie w IndexedDB.':'Pomiar termiczny zapisany.');};save().catch(e=>status(e.message,true));}
    if(form.id==='f44ArchQuiz'){const ok=v.answer==='a';$('#f44ArchQuizResult').innerHTML=`<p class="f44-${ok?'good':'bad'}">${ok?'Poprawnie.':'Niepoprawnie.'} Kontroler pamięci obsługuje komunikację CPU z RAM.</p>`;addLearning('Quiz architektury CPU',ok?'Zaliczone':'Powtórka');}
    if(form.id==='f44BatteryForm'){const voltage=Number(v.voltage),current=Number(v.current);if(!(voltage>0&&voltage<=60&&current>=0&&current<=10)){status('Wartości poza zakresem edukacyjnego kalkulatora.',true);return;}const power=voltage*current;state.battery.unshift({id:uid('BAT'),voltage,current,power,profile:clean(v.profile,40),notes:clean(v.notes,500),createdAt:now()});persist();$('#f44BatteryResult').innerHTML=`<b>${fmt(power)} W</b><p>${fmt(voltage)} V × ${fmt(current)} A = ${fmt(power)} W</p>`;$('#f44BatteryForm').reset();$('#f44BatteryForm').elements.voltage.value='20';$('#f44BatteryForm').elements.current.value='3.25';addLearning('Battery & Charging Lab',`${fmt(power)} W`);}
    if(form.id==='f44NetworkForm'){try{const r=calculateSubnet(v.ip,v.cidr);$('#f44NetworkResult').innerHTML=`<div class="f44-kv"><span>Maska</span><b>${r.mask}</b><span>Network</span><b>${r.network}</b><span>Broadcast</span><b>${r.broadcast}</b><span>Zakres hostów</span><b>${r.firstHost} – ${r.lastHost}</b><span>Liczba hostów</span><b>${r.hostCount}</b><span>VLAN ćwiczeniowy</span><b>${esc(v.vlan||'—')}</b></div>`;state.network.unshift({...r,vlan:clean(v.vlan,10),createdAt:now()});persist();}catch(e){$('#f44NetworkResult').textContent=e.message;}}
    if(form.id==='f44CaseForm'){addCase({title:clean(v.title,180),device:clean(v.device,160),symptom:clean(v.symptom,1000),cause:clean(v.cause,1000),resolution:clean(v.resolution,1200),tags:clean(v.tags,300),source:clean(v.source,300)});render();status('Przypadek zapisany lokalnie.');}
    if(form.id==='f44TicketForm'){const parts=Number(v.parts),labor=Number(v.labor);if(parts<0||labor<0||parts>100000||labor>100000){status('Nieprawidłowy koszt.',true);return;}addTicket({client:clean(v.client,140),device:clean(v.device,180),serial:clean(v.serial,120),status:clean(v.status,40),problem:clean(v.problem,1200),parts,labor,notes:clean(v.notes,1000)});render();status('Zlecenie dodane do lokalnego Service Manager.');}
    if(form.id==='f44DocForm'){const f=form.elements.file.files[0];if(!f)return;storeLibraryFile(f,v.tags,v.source).then(()=>{render();status('Dokument zapisany w IndexedDB tej przeglądarki.');}).catch(e=>status(e.message,true));}
  }
  async function processBios(form,v){const a=form.elements.biosA.files[0],b=form.elements.biosB.files[0];if(!a)throw new Error('Wybierz wsad A.');if(a.size>MAX_BIOS_FILE||(b&&b.size>MAX_BIOS_FILE))throw new Error('Limit rozmiaru wsadu BIOS to 32 MiB.');const out=$('#f44BiosResult');out.textContent='Czytanie plików w pamięci i obliczanie SHA-256…';const ab=await a.arrayBuffer();const shaA=await sha256(ab);let result=`<p><b>Wsad A:</b> ${esc(a.name)} · ${fmt(a.size)} B</p><code>${shaA}</code>`;state.bios.unshift({id:uid('BIOS'),name:a.name,sha256:shaA,size:String(a.size),date:now(),notes:clean(v.notes,800)});if(b){const bb=await b.arrayBuffer();const shaB=await sha256(bb);const diff=compareBios(ab,bb);state.bios.unshift({id:uid('BIOS'),name:b.name,sha256:shaB,size:String(b.size),date:now(),notes:`Porównanie z ${a.name}`});result+=`<p><b>Wsad B:</b> ${esc(b.name)} · ${fmt(b.size)} B</p><code>${shaB}</code><div class="f44-kv"><span>Różne bajty</span><b>${fmt(diff.differentBytes)}</b><span>Zakresy zmian</span><b>${diff.changedRanges}</b><span>Równa długość</span><b>${diff.sameLength?'Tak':'Nie'}</b></div><p>Zakresy zmian (offsety hex): ${diff.ranges.map(r=>`${r[0].toString(16)}–${r[1].toString(16)}`).join(', ')||'brak'}</p>`;}persist();out.innerHTML=result;$('#f44BiosList').innerHTML=renderBiosList();status('SHA-256 obliczony. Surowe wsady nie zostały zachowane.');}
  async function analyzeDisk(file){if(file.size>MAX_DISK_IMAGE)throw new Error('Limit obrazu w tej przeglądarce to 64 MiB.');if(file.size<512)throw new Error('Plik jest mniejszy niż podstawowy sektor 512 B.');const head=await file.slice(0,Math.min(file.size,1024*1024)).arrayBuffer();const parsed=parseDiskHeader(new Uint8Array(head),file.size);diskResult={name:file.name,...parsed};const host=$('#f44DiskResult');host.innerHTML=`<h3>${esc(file.name)}</h3><div class="f44-kv"><span>MBR 0x55AA</span><b>${parsed.mbrSignature?'Wykryto':'Nie wykryto'}</b><span>GPT EFI PART</span><b>${parsed.gptSignature?'Wykryto':'Nie wykryto'}</b><span>Rozmiar</span><b>${fmt(file.size/1024/1024)} MiB</b></div><h4>Wpisy MBR</h4>${parsed.partitions.length?parsed.partitions.map(p=>`<p>Partycja ${p.index}: typ ${p.type}, start LBA ${p.startLBA}, sektory ${p.sectors}</p>`).join(''):empty('Brak wpisów MBR w podstawowym sektorze.') }<p class="f44-note">Analiza tylko do odczytu. Wynik nie potwierdza poprawności systemu plików ani możliwości odzyskania danych.</p>`;}

  function startSim(id){const s=SIMS.find(x=>x.id===id);if(!s)return;simulator={id,index:0,score:0,total:s.steps.length,answers:[]};setTab('simulator');}
  function answerSim(index){if(!simulator)return;const s=SIMS.find(x=>x.id===simulator.id);const q=s?.steps[simulator.index];if(!q)return;const option=q.opts[index];if(!option)return;simulator.score+=option[1];simulator.answers.push({question:q.q,answer:option[0],correct:!!option[1],explanation:option[2]});const fb=$('#f44SimFeedback');if(fb)fb.innerHTML=`<div class="f44-${option[1]?'good':'bad'}"><b>${option[1]?'Dobrze!':'Nie tym razem.'}</b><p>${esc(option[2])}</p></div>`;addLearning(s.title,option[1]?'Poprawny krok':'Błędny krok — powtórka');simulator.index++;if(simulator.index>=s.steps.length){const done={id:uid('SIM'),scenario:s.id,title:s.title,score:simulator.score,total:simulator.total,answers:simulator.answers,createdAt:now()};state.simulatorRuns.push(done);persist();simulator=null;ROOT.innerHTML=`<section class="f44-card"><span class="f44-kicker">WYNIK SYMULACJI</span><h2>${esc(s.title)}</h2><div class="f44-coach-score"><b>${done.score}/${done.total}</b><span>punkty za bezpieczne decyzje</span></div><p>${done.score===done.total?'Świetnie — wszystkie kroki prawidłowe.':'Przejrzyj wyjaśnienia i powtórz scenariusz.'}</p><ol class="f44-list">${done.answers.map(x=>`<li><b>${esc(x.answer)}</b><p>${esc(x.explanation)}</p></li>`).join('')}</ol><div class="f44-actions">${button('Wybierz kolejny scenariusz','quit-sim','primary')}${button('Wróć na pulpit','goto-overview')}</div></section>`;status(`Symulacja zakończona: ${done.score}/${done.total} pkt.`);}else render();}

  async function onAction(action,el){const id=el.dataset.id;
    if(action.startsWith('goto-')){const target=action.slice(5);if(tabs.some(t=>t[0]===target))setTab(target);else navigateHost(target);return;}
    if(action==='delete-model')deleteRow('models',id);
    if(action==='delete-bios')deleteRow('bios',id);
    if(action==='delete-thermal')deleteRow('thermal',id);
    if(action==='delete-battery')deleteRow('battery',id);
    if(action==='delete-case')deleteRow('cases',id);
    if(action==='delete-ticket')deleteRow('tickets',id);
    if(action==='verify-case'){const row=state.cases.find(x=>x.id===id);if(row){row.status='zweryfikowany lokalnie';persist();render();status('Przypadek oznaczony jako zweryfikowany lokalnie. Wymaga niezależnego sprawdzenia przed publikacją.');}}
    if(action==='architecture-select'){sessionStorage.setItem('f44ArchSelected',id);render();}
    if(action==='rotate-board'){const g=$('#f44BoardGroup');if(g){const a=(Number(g.dataset.angle||0)+1)%4;g.dataset.angle=a;g.style.transformOrigin='center';g.style.transform=`perspective(950px) rotateX(${a*7}deg) rotateY(${a%2?12:-12}deg) rotateZ(${a*3}deg)`;}}
    if(action==='reset-board'){const g=$('#f44BoardGroup');if(g){g.dataset.angle='0';g.style.transform='none';}}
    if(action==='export-cases')exportJSON({format:'NAUKA-FIX44-CASE-PACK',version:1,exportedAt:now(),cases:state.cases},'nauka-fix44-przypadki.json');
    if(action==='import-cases')$('#f44CaseImport')?.click();
    if(action==='export-service')exportJSON({format:'NAUKA-FIX44-SERVICE-EXPORT',version:1,exportedAt:now(),tickets:state.tickets},'nauka-fix44-zlecenia.json');
    if(action==='print-tickets'){const rows=state.tickets.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.device)}</td><td>${esc(x.client)}</td><td>${esc(x.status)}</td><td>${fmt(x.parts+x.labor)} zł</td></tr>`).join('');const w=window.open('','_blank');if(w){w.document.write(`<!doctype html><meta charset="utf-8"><title>Raport zleceń FIX44</title><h1>Zlecenia serwisowe</h1><table border="1" cellspacing="0" cellpadding="6"><tr><th>ID</th><th>Urządzenie</th><th>Klient</th><th>Status</th><th>Wartość</th></tr>${rows}</table>`);w.document.close();w.print();}}
    if(action==='run-qa'){qaResults=runSelfChecks();$('#f44QAResults').innerHTML=renderQAResults();status(`Kontrola QA: ${qaResults.filter(x=>x.ok).length}/${qaResults.length} PASS`,qaResults.some(x=>!x.ok));}
    if(action==='export-qa')exportJSON({build:BUILD,createdAt:now(),results:qaResults},'nauka-fix44-raport-qa.json');
    if(action==='start-sim')startSim(id);
    if(action==='sim-answer')answerSim(Number(el.dataset.index));
    if(action==='quit-sim'){simulator=null;render();}
    if(action==='export-state')exportJSON({format:'NAUKA-FIX44-LOCAL-STATE',version:1,exportedAt:now(),state},'nauka-fix44-dane-lokalne.json');
    if(action==='export-sources')exportJSON({format:'NAUKA-FIX44-SOURCE-INDEX',version:1,createdAt:now(),sources:SOURCES},'nauka-fix44-indeks-zrodel.json');
    if(action==='check-updates')checkUpdates();
    if(action==='import-update')$('#f44UpdateFile')?.click();
    if(action==='download-doc'){const row=await getLibraryFile(id);if(!row)throw new Error('Nie znaleziono pliku w IndexedDB.');downloadBlob(new Blob([row.data],{type:row.type}),row.name);}
    if(action==='delete-doc'){await deleteLibraryFile(id);render();status('Dokument usunięty lokalnie.');}
    if(action==='goto-courses'){navigateHost('courses');}
    if(action==='goto-cloudchat'){navigateHost('cloudchat');}
  }

  async function checkUpdates(){const out=$('#f44UpdateResult');if(!out)return;out.textContent='Pobieranie lokalnego manifestu…';try{const res=await fetch('assets/knowledge-updates-fix44.json',{cache:'no-cache'});if(!res.ok)throw new Error(`HTTP ${res.status}`);const manifest=await res.json();const integrity=await sha256(new TextEncoder().encode(JSON.stringify({version:manifest.version,updatedAt:manifest.updatedAt,sources:manifest.sources})).buffer);const valid=integrity===manifest.integrity;out.innerHTML=`<div class="f44-${valid?'good':'bad'}"><b>${valid?'Manifest integralny':'Błąd integralności manifestu'}</b><p>Wersja ${esc(manifest.version)} · ${esc(manifest.updatedAt)} · ${manifest.sources?.length||0} źródeł</p><p>SHA-256: <code>${esc(integrity)}</code></p></div>`;if(valid){state.updates.unshift({version:manifest.version,updatedAt:manifest.updatedAt,integrity,checkedAt:now(),status:'verified'});persist();status('Manifest źródeł sprawdzony. To indeks źródeł, nie automatyczna aktualizacja firmware.');}else status('Manifest nie przeszedł kontroli integralności.',true);}catch(e){out.textContent=`Nie udało się sprawdzić manifestu: ${clean(e.message,180)}`;status(e.message,true);}}
  function importCaseFile(file){if(file.size>4*1024*1024){status('Pakiet przypadków przekracza limit 4 MiB.',true);return;}file.text().then(raw=>{const data=JSON.parse(raw);if(data.format!=='NAUKA-FIX44-CASE-PACK'||!Array.isArray(data.cases))throw new Error('Nieprawidłowy format pakietu.');const rows=data.cases.slice(0,100).map(x=>({id:uid('CASE'),title:clean(x.title,180),device:clean(x.device,160),symptom:clean(x.symptom,1000),cause:clean(x.cause,1000),resolution:clean(x.resolution,1200),tags:clean(x.tags,300),source:clean(x.source,300),status:'importowany — niezweryfikowany',createdAt:now()})).filter(x=>x.title&&x.symptom);state.cases.push(...rows);persist();render();status(`Zaimportowano ${rows.length} przypadków jako niezweryfikowane.`);}).catch(e=>status(`Import nieudany: ${clean(e.message,180)}`,true));}
  function importUpdateFile(file){if(file.size>512*1024){status('Indeks źródeł przekracza limit 512 KiB.',true);return;}file.text().then(raw=>{const data=JSON.parse(raw);if(data.format!=='NAUKA-FIX44-SOURCE-INDEX'||!Array.isArray(data.sources))throw new Error('Nieprawidłowy indeks źródeł.');const urls=data.sources.filter(x=>/^https:\/\//.test(x.url||'')).length;$('#f44UpdateResult').textContent=`Zaimportowano ${Math.min(data.sources.length,100)} wpisów indeksu (${urls} adresów HTTPS). To katalog odnośników — nie potwierdza autentyczności dokumentów.`;status('Indeks źródeł wczytany. Zweryfikuj domenę i licencję każdego dokumentu.');}).catch(e=>status(`Import manifestu nieudany: ${clean(e.message,180)}`,true));}

  ROOT.addEventListener('submit',handleSubmit);
  ROOT.addEventListener('click',event=>{const btn=event.target.closest('[data-f44-action]');if(btn){event.preventDefault();onAction(btn.dataset.f44Action,btn).catch(e=>status(e.message,true));return;}const part=event.target.closest('[data-f44-part]');if(part){const item=PARTS[part.dataset.f44Part];if(item)$('#f44ExplorerDetail').innerHTML=`<span class="f44-kicker">EDU COMPONENT / ${esc(part.dataset.f44Part)}</span><h3>${esc(item[0])}</h3><p>${esc(item[1])}</p><b>Co sprawdzić</b><p>${esc(item[2])}</p>`;}});
  ROOT.addEventListener('change',event=>{
    if(event.target.id==='f44ModelSearch')$('#f44ModelList').innerHTML=renderModels(event.target.value);
    if(event.target.id==='f44DocSearch')$('#f44DocList').innerHTML=renderDocList(event.target.value);
    if(event.target.id==='f44DiskImage'){const f=event.target.files[0];if(f)analyzeDisk(f).catch(e=>status(e.message,true));}
    if(event.target.id==='f44CaseImport'&&event.target.files[0])importCaseFile(event.target.files[0]);
    if(event.target.id==='f44UpdateFile'&&event.target.files[0])importUpdateFile(event.target.files[0]);
    if(event.target.name==='image'&&event.target.files[0]){$('#f44ThermalPreview').textContent=`Załącznik lokalny: ${event.target.files[0].name} (${fmt(event.target.files[0].size/1024)} KiB).`}
    if(event.target.dataset.f44TicketStatus){const row=state.tickets.find(x=>x.id===event.target.dataset.f44TicketStatus);if(row){row.status=clean(event.target.value,40);persist();status(`Status zlecenia ${row.id} zmieniony.`);}}
  });
  PAGE.querySelectorAll('[data-f44-tab]').forEach(btn=>btn.addEventListener('click',()=>setTab(btn.dataset.f44Tab)));
  PAGE.addEventListener('click',event=>{const host=event.target.closest('[data-f44-host-view]');if(host)navigateHost(host.dataset.f44HostView);});
  render();

  const API=Object.freeze({build:BUILD,getState:()=>JSON.parse(JSON.stringify(state)),normalizeState:normalize,calculateSubnet,compareBios,parseDiskHeader,calculatePower:(v,a)=>Number(v)*Number(a),runSelfChecks,addModel,addTicket,addCase,setTab,checkUpdates,storeLibraryFile,version:1});
  window.NP_NAUKA_FIX44=API;
  status('Master Service Center FIX44 gotowe. Dane są lokalne; operacje firmware, dysku i routera pozostają tylko do odczytu / symulacji.');
})();
